style.css:
@-moz-document domain("youtube.com") {
/* Hide YouTube's built-in logo */
  ytd-topbar-logo-renderer {
    display: none !important;
  }

  /* Insert your custom logo or GIF */
  #masthead #start {
    background-image: url("https://media.tenor.com/Gl9DKp1plC8AAAAi/kokichi-sprite.gif"); /* Replace with your GIF URL */
    background-size: contain;
    background-repeat: no-repeat;
    width: 200px;  /* Adjust width */
    height: 80px;  /* Adjust height */
    display: inline-block;
    margin-left: 50px; /* Moves logo 20px to the right */
  }
}

@-moz-document domain("youtube.com") {
/* Add right margin to hamburger */
  #guide-button {  /* This is usually the hamburger menu ID */
    margin-right: 50px; /* Adjust spacing */
  }
}
